    { term: "Cash crops", def: "Crops grown for sale rather than local use, such as cocoa, coffee, tea and tobacco, whose export volume broadened under colonial rule." },
    { term: "Commercial transition", def: "Africa's shift towards exporting raw materials and cash crops in response to rising industrial demand in Western Europe." },
    { term: "Divide and rule", def: "The colonial strategy that set African groups against one another and contributed to lasting divisions." }
